            ):
                candidates.append(candidate)
        candidates.extend(
            Candidate(self.snapshot, Target.from_unit(unit), "owner_constructor")
            for unit in self.context.parsed.units
            if unit.parent_id in owner_ids and unit.name in {"constructor", "__init__", "new"}
