        await self.inference.store_judgments(
            request.evidence.encoded,
            {check.id: self.planner.questions[check.id] for check in request.checks},
            request.questions,
            response,
        )
        self.results.accept(
            request,
            response.answers,
            response.model,
            prediction.cached,
            {**prediction.metrics, "phase": "initial"},
        )
        return "accepted"

