        return min(self.config.max_retry_delay, 0.5 * 2**attempt + random.random() * 0.25)  # noqa: S311

    async def __aenter__(self) -> Self:
        return self

    async def __aexit__(self, *_exc: object) -> None:
        await self.http.aclose()

