    pending = [root]
    while pending:
        node = pending.pop()
        if node.is_error or node.is_missing:
            return node.start_point.row + 1
        pending.extend(reversed([child for child in node.children if child.has_error or child.is_missing]))
    return 1


_NAME_NODES = frozenset({
    "identifier",
    "property_identifier",
    "field_identifier",
    "type_identifier",
    "bareword",
    "function",
    "method",
})
_CALL_NODES = frozenset({
    "call",
    "call_expression",
    "func1op_call_expression",
    "function_call_expression",
    "method_call_expression",
})
_VALIDATION_NODES = _CALL_NODES | frozenset({
    "assert_expression",
    "assert_statement",
    "binary_expression",
    "boolean_operator",
    "comparison_expression",
    "comparison_operator",
    "conditional_expression",
    "conditional_statement",
    "if_expression",
    "if_statement",
    "in_operator",
    "is_operator",
    "macro_invocation",
    "match_expression",
    "type_check",
    "unary_expression",
    "unless_statement",
})
_FALLBACK_NODES = _CALL_NODES | frozenset({
    "assignment_expression",
    "binary_expression",
    "boolean_operator",
    "catch_clause",
    "coalesce_expression",
    "conditional_expression",
    "conditional_statement",
    "default_parameter",
    "else_clause",
    "eval_expression",
    "except_clause",
    "finally_clause",
    "if_expression",
    "if_statement",
    "macro_invocation",
    "match_expression",
    "optional_parameter",
    "rescue_clause",
    "try_expression",
    "try_statement",
    "unless_statement",
})
_SENTINEL_NODES = frozenset({"none", "null", "undefined", "undef", "undef_expression"})
