    name = Path(path).name
    return (
        any(part in {"test", "tests", "__tests__"} for part in Path(path).parts)
        or name.startswith("test_")
        or name.endswith(("_test.py", ".t"))
        or ".test." in name
        or ".spec." in name
    )


