def _read_source(root: Path, path: str, limit: int) -> bytes:
    """Open every component relative to a trusted root, without following symlinks."""
    parts = Path(path).parts
    if not parts or Path(path).is_absolute() or any(part in {"..", "."} for part in parts):
        raise OSError("evidence path is not project-relative")
    if not hasattr(os, "O_NOFOLLOW") or os.open not in os.supports_dir_fd:
        raise OSError("safe evidence reads require no-follow, directory-relative file access")
    directory = os.open(root, os.O_RDONLY | os.O_DIRECTORY)
    try:
        for part in parts[:-1]:
            child = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=directory)
            os.close(directory)
            directory = child
        descriptor = os.open(parts[-1], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=directory)
        with os.fdopen(descriptor, "rb") as stream:
            before = os.fstat(stream.fileno())
            if not stat.S_ISREG(before.st_mode):
                raise OSError("evidence is not a regular file")
            source = stream.read(limit + 1)
            after = os.fstat(stream.fileno())
            if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
                raise OSError("evidence changed during snapshot read")
            return source
    finally:
        os.close(directory)


def _reference_targets(parsed: ParsedFile) -> Iterator[tuple[Reference, Target]]:
    """Associate occurrences with their innermost lexical unit in a single sweep."""
    units = iter(parsed.units)
    following = next(units, None)
    stack: list[Target] = []
    file = Target.from_file(parsed)
    for reference in sorted(parsed.references, key=lambda item: item.start_byte):
        while following is not None and following.start_byte <= reference.start_byte:
            while stack and following.start_byte >= stack[-1].end_byte:
                stack.pop()
            stack.append(Target.from_unit(following))
            following = next(units, None)
        while stack and reference.end_byte > stack[-1].end_byte:
            stack.pop()
        yield reference, stack[-1] if stack else file


